/* Tipo 0 = código de barras. */
SELECT a.Id, o.Codigo, 0
FROM #Codigos o
JOIN [Articulos] a ON a.Codigo = o.ArticuloCodigo
WHERE NOT EXISTS (SELECT 1 FROM [CodigosArticulo] k WHERE k.Codigo = o.Codigo);
GO

DROP TABLE #Codigos;
GO

DECLARE @total int = (SELECT COUNT(*) FROM [CodigosArticulo]);
PRINT 'Códigos de barra: ' + CAST(@total AS varchar(10)) + ' en total.';
GO
